import Foundation
import CRMCore

func runInboxLinkDealChecks(directory:URL) async throws -> Int {
    var count=0
    func expect(_ v:Bool,_ m:String) throws {guard v else {throw CheckFailure(message:m)};count += 1}
    let d=try JSONSerialization.jsonObject(with:Data(contentsOf:directory.appendingPathComponent("inbox-link-deal.json"))) as! [String:Any],reads=APIDealReadRepository(transport:FixtureDealReadTransport(directory:directory)),port=FixtureInboxLinkDealPort(directory:directory)
    func context(_ x:[String:Int])->InboxConversationFilesContext {InboxConversationFilesContext(business:x["business"]!,conversation:x["conversation"]!,epoch:x["epoch"]!,revision:x["revision"]!)}
    func reference(_ c:InboxConversationFilesContext,id:Int=5701,raw:String="005701") async throws -> QualifiedDealReference {var s=DealReferenceSession();s.bind(c);s.show();s.update(raw,input:s.input);let t=s.begin(expected:s.control)!;let source=try await reads.deal(business:c.business,id:id);s.accept(source,ticket:t);s.use(expected:s.control);return s.choice!}
    func review(_ c:InboxConversationFilesContext,_ raw:String,id:Int,input:String) async throws -> InboxLinkDealReview {let s=InboxLinkDealSource.decode(Data(raw.utf8),context:c)!,ref=try await reference(c,id:id,raw:input),auth=port.grants.compactMap {$0.authorization(for:c)}.first!;return InboxLinkDealReview(source:s,authorization:auth,candidate:InboxLinkDealCandidate(source:s,reference:ref)!,visit:1)}
    for row in d["source_cases"] as! [[String:Any]] {let s=InboxLinkDealSource.decode(Data((row["response_json"] as! String).utf8),context:context(row["context"] as! [String:Int]));try expect((s != nil)==row["valid"] as! Bool,"Exact generic three-link source/null/alias \(row["name"]!)");if let s {try expect(s.valid && Mirror(reflecting:s).children.count==5,"Deal link source retained hidden metadata/permission")}}
    let c=context(d["context"] as! [String:Int]),original=InboxLinkDealSource.decode(Data((d["source_json"] as! String).utf8),context:c)!
    for row in d["candidate_scope_cases"] as! [[String:Any]] {let ctx=context(row["context"] as! [String:Int]),ref=try await reference(ctx,id:ctx.business==101 ? 5701:6701,raw:ctx.business==101 ? "005701":"006701");try expect((InboxLinkDealCandidate(source:original,reference:ref) != nil)==row["valid"] as! Bool,"Qualified Deal owner \(row["name"]!)")}
    for row in d["receipt_cases"] as! [[String:Any]] {let r=try await review(context(row["context"] as! [String:Int]),row["source_json"] as! String,id:row["deal_id"] as! Int,input:row["raw_input"] as! String);var l=InboxLinkDealLedger();let a=l.begin(r)!;try expect((InboxLinkDealReceipt.decode(Data((row["response_json"] as! String).utf8),attempt:a) != nil)==row["valid"] as! Bool,"Conditional Client AND Lead receipt \(row["name"]!)")}
    for row in d["conditional_matrix"] as! [[String:Any]] {let r=try await review(context(row["context"] as! [String:Int]),row["source_json"] as! String,id:row["deal_id"] as! Int,input:row["raw_input"] as! String);var l=InboxLinkDealLedger();let a=l.begin(r)!;let receipt=InboxLinkDealReceipt.decode(Data((row["response_json"] as! String).utf8),attempt:a)!;try expect(receipt.source.client==row["expected_client"] as? Int && receipt.source.lead==row["expected_lead"] as? Int,"Preserve/fill/null Deal Lead matrix \(row["name"]!)")}
    let r=try await review(c,d["source_json"] as! String,id:5701,input:"005701"),auth=r.authorization;var l=InboxLinkDealLedger();let a=l.begin(r)!,body=try JSONSerialization.jsonObject(with:a.preparedBody()) as! [String:Int];try expect(body==["deal_id":5701] && a.path=="/api/inbox/conversations/901/link-deal/" && a.query.isEmpty && a.headers.isEmpty,"Deal invented Client/Lead/body/query/version/key")
    try expect(l.begin(r)==nil && !l.acknowledge(auth,record:l.visible(auth)!),"Pending Deal repeated/acknowledged");l.complete(a,outcome:try await port.execute(a));let known=l.visible(auth)!;try expect(known.phase == .response && known.result?.source.deal==5701 && known.result?.source.client==701 && known.result?.source.lead==81 && known.attempt.review.source.deal==111,"Deal fake result overwrote original Client/Lead or source");l.complete(a,outcome:.unknown);try expect(l.visible(auth)==known && l.acknowledge(auth,record:known),"Late result/known ack lost Deal history")
    let u=l.begin(r)!;l.complete(u,outcome:.unknown);let unknown=l.visible(auth)!,next=InboxConversationFilesContext(business:101,conversation:901,epoch:2,revision:2),ref=try await reference(next),matching=InboxLinkDealSource.decode(try JSONSerialization.data(withJSONObject:["id":901, "business":101, "deal":5701, "client":701, "lead":81, "updated_at":"matching GET"]),context:next)!,nAuth=port.grants[0].authorization(for:next)!
    try expect(l.visible(nAuth)==unknown && !l.acknowledge(nAuth,record:unknown) && l.begin(InboxLinkDealReview(source:matching,authorization:nAuth,candidate:InboxLinkDealCandidate(source:matching,reference:ref)!,visit:2))==nil && unknown.attempt==u && unknown.attempt.review.candidate.reference.rawInput=="005701","Matching three links/GET/new epoch recovered unknown or changed raw input")
    for grant in [SyntheticInboxLinkDealGrant(business:101,conversation:901,actor:5001,dealsUpdate:false,conversationsUpdate:true),SyntheticInboxLinkDealGrant(business:101,conversation:901,actor:5001,dealsUpdate:true,conversationsUpdate:false),SyntheticInboxLinkDealGrant(business:101,conversation:902,actor:5001,dealsUpdate:true,conversationsUpdate:true),SyntheticInboxLinkDealGrant(business:101,conversation:901,actor:0,dealsUpdate:true,conversationsUpdate:true)] {try expect(grant.authorization(for:c)==nil,"VIEW/one-of-two/wrong Deal grant authorized")}
    let other=SyntheticInboxLinkDealGrant(business:101,conversation:901,actor:6002,dealsUpdate:true,conversationsUpdate:true).authorization(for:next)!;try expect(l.visible(other)==nil && l.blocked(business:101,conversation:901) && !l.blocked(business:202,conversation:951),"Deal actor visibility/barrier lost")
    for status in [201,202,204,400,409,500] {var wrong=InboxLinkDealLedger();let attempt=wrong.begin(r)!;wrong.complete(attempt,outcome:.response(status:status,data:try JSONSerialization.data(withJSONObject:["id":901,"business":101,"deal":5701,"client":701,"lead":81,"updated_at":"fake"])));try expect(wrong.visible(auth)?.phase == .unknown,"Non-plain200 Deal response became known")}
    var rejected=InboxLinkDealLedger();let rejectedAttempt=rejected.begin(r)!;rejected.complete(rejectedAttempt,outcome:.rejectedWithoutWrite);let reject=rejected.visible(auth)!;try expect(reject.phase == .rejected && rejected.acknowledge(auth,record:reject) && rejected.records.count==1,"Definite no-write Deal rejection lost attempt")
    return count
}
